result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/check_deps.py", "content": "#!/usr/bin/env python3
"""License-compatibility checker.

Loads a compatibility knowledge base (licenses.json) and a dependency graph
(deps.json) of the form:

    {"app": {"license": "Apache-2.0", "deps": ["libA", "libB"]}, ...}

Reports every edge (including transitive ancestor->descendant relationships)
whose parent license may not link against the child license, with the full
dependency path. Rejects cyclic graphs with a clear error.
"""

import json
import sys


class CyclicDependencyError(ValueError):
    """Raised when the dependency graph contains a cycle."""


def load_json(path):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def _validate_licenses(graph, kb):
    known = set(kb["may_link"])
    for name, node in graph.items():
        lic = node.get("license")
        if lic not in known:
            raise ValueError(
                f"Node {name!r} has unknown license {lic!r}; "
                f"known licenses: {sorted(known)}"
            )


def assert_acyclic(graph):
    """Raise CyclicDependencyError if the graph contains a cycle."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {name: WHITE for name in graph}
    path = []

    def visit(node):
        color[node] = GRAY
        path.append(node)
        for dep in graph[node].get("deps", []):
            if dep not in graph:
                raise ValueError(f"Unknown dependency {dep!r} (referenced by {node!r})")
            if color[dep] == GRAY:
                cycle = path[path.index(dep):] + [dep]
                raise CyclicDependencyError(
                    "Cyclic dependency graph detected: " + " -> ".join(cycle)
                )
            if color[dep] == WHITE:
                visit(dep)
        path.pop()
        color[node] = BLACK

    for node in graph:
        if color[node] == WHITE:
            visit(node)


def check(graph, kb):
    """Return a list of violation dicts for the dependency graph."""
    _validate_licenses(graph, kb)
    assert_acyclic(graph)

    may_link = kb["may_link"]
    dist_restricted = kb.get("distribution_restricted", {})

    # Roots: nodes nobody depends on. Every node is reachable from some root
    # in an acyclic graph, so this covers all edges without duplicates.
    depended_on = {dep for node in graph.values() for dep in node.get("deps", [])}
    roots = [name for name in graph if name not in depended_on]

    violations = []
    seen = set()

    def record(path, parent_lic, child, child_lic, reason):
        key = (tuple(path), reason)
        if key in seen:
            return
        seen.add(key)
        violations.append({
            "path": list(path),
            "parent_license": parent_lic,
            "child": child,
            "child_license": child_lic,
            "reason": reason,
        })

    def walk(path):
        parent = path[-1]
        parent_lic = graph[parent]["license"]
        for child in graph[parent].get("deps", []):
            child_path = path + [child]
            child_lic = graph[child]["license"]

            if not may_link[parent_lic][child_lic]:
                record(child_path, parent_lic, child, child_lic,
                       f"{parent_lic} may not link against {child_lic}")

            if child_lic in dist_restricted and parent_lic != child_lic:
                record(child_path, parent_lic, child, child_lic,
                       dist_restricted[child_lic])

            walk(child_path)

    for root in roots:
        walk([root])

    return violations


def format_violations(violations):
    lines = []
    for v in violations:
        lines.append(
            "VIOLATION: " + " -> ".join(v["path"])
            + f"  ({v['parent_license']} above {v['child_license']})"
            + f"\n  reason: {v['reason']}"
        )
    return "\n".join(lines)


def main(argv=None):
    argv = argv if argv is not None else sys.argv[1:]
    deps_path = argv[0] if argv else "deps.json"
    kb_path = argv[1] if len(argv) > 1 else "licenses.json"

    graph = load_json(deps_path)
    kb = load_json(kb_path)

    try:
        violations = check(graph, kb)
    except CyclicDependencyError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 2

    if violations:
        print(format_violations(violations))
        print(f"\n{len(violations)} violation(s) found.")
        return 1

    print("No license violations found.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
"})
