result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_check_deps.py", "content": "import json
import os

import pytest

from check_deps import CyclicDependencyError, check, load_json, main

HERE = os.path.dirname(os.path.abspath(__file__))
KB = load_json(os.path.join(HERE, "licenses.json"))

SAMPLE_GRAPH = {
    "app": {"license": "Apache-2.0", "deps": ["libA", "libB"]},
    "libA": {"license": "MIT", "deps": ["libC"]},
    "libC": {"license": "GPL-3.0", "deps": []},
    "libB": {"license": "BSL-1.1", "deps": []},
}


def paths_of(violations):
    return {tuple(v["path"]) for v in violations}


def test_sample_graph_yields_exactly_two_violations():
    violations = check(SAMPLE_GRAPH, KB)
    paths = paths_of(violations)
    assert paths == {
        # Apache-2.0 cannot link (even transitively) against GPL-3.0
        ("app", "libA", "libC"),
        # BSL-1.1 dependency: internal use only, distribution must be flagged
        ("app", "libB"),
    }
    assert len(violations) == 2

    gpl_v = next(v for v in violations if tuple(v["path"]) == ("app", "libA", "libC"))
    assert gpl_v["parent_license"] == "Apache-2.0"
    assert gpl_v["child_license"] == "GPL-3.0"

    bsl_v = next(v for v in violations if tuple(v["path"]) == ("app", "libB"))
    assert bsl_v["child_license"] == "BSL-1.1"
    assert "internal use" in bsl_v["reason"]


def test_clean_all_mit_graph_has_no_violations():
    graph = {
        "app": {"license": "MIT", "deps": ["libA", "libB"]},
        "libA": {"license": "MIT", "deps": ["libC"]},
        "libB": {"license": "MIT", "deps": ["libC"]},
        "libC": {"license": "MIT", "deps": []},
    }
    assert check(graph, KB) == []


def test_cycle_raises():
    graph = {
        "a": {"license": "MIT", "deps": ["b"]},
        "b": {"license": "MIT", "deps": ["c"]},
        "c": {"license": "MIT", "deps": ["a"]},
    }
    with pytest.raises(CyclicDependencyError, match="[Cc]yclic"):
        check(graph, KB)


def test_self_cycle_raises():
    graph = {"a": {"license": "MIT", "deps": ["a"]}}
    with pytest.raises(CyclicDependencyError):
        check(graph, KB)


def test_unknown_dependency_is_rejected():
    graph = {"app": {"license": "MIT", "deps": ["ghost"]}}
    with pytest.raises(ValueError, match="ghost"):
        check(graph, KB)


def test_unknown_license_is_rejected():
    graph = {"app": {"license": "WTFPL", "deps": []}}
    with pytest.raises(ValueError, match="WTFPL"):
        check(graph, KB)


def test_cli_exit_codes(tmp_path):
    bad = tmp_path / "bad.json"
    bad.write_text(json.dumps(SAMPLE_GRAPH))
    assert main([str(bad), os.path.join(HERE, "licenses.json")]) == 1

    good = tmp_path / "good.json"
    good.write_text(json.dumps({"app": {"license": "MIT", "deps": []}}))
    assert main([str(good), os.path.join(HERE, "licenses.json")]) == 0

    cyclic = tmp_path / "cyclic.json"
    cyclic.write_text(json.dumps({
        "x": {"license": "MIT", "deps": ["y"]},
        "y": {"license": "MIT", "deps": ["x"]},
    }))
    assert main([str(cyclic), os.path.join(HERE, "licenses.json")]) == 2


def test_sample_deps_dot_json_if_present(tmp_path):
    """If the canonical deps.json exists next to the checker, it must yield
    exactly the two documented violations."""
    deps = os.path.join(HERE, "deps.json")
    if not os.path.exists(deps):
        pytest.skip("deps.json not present")
    graph = load_json(deps)
    violations = check(graph, KB)
    assert len(violations) == 2
    assert paths_of(violations) == {("app", "libA", "libC"), ("app", "libB")}
"})
